-- Restore captured quest spell reward previews
-- 2026_11_10_53_world_everlake_quest_reward_previews.sql: generated by tools/forever-data in wow-project-everlake from public WoW Forever data.
-- Sources (pins): eg-link 9fcae73cc74fea4f1c4f, wago 1.60.1.70862
-- Written against the fork world core 343fe6fb + world-data 24a3b39e + reviewed drafts.
-- Efficient Games CC BY 4.0. Display only: no learning behavior or quest availability changes.
-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';
SET SESSION autocommit = 0;
CREATE TEMPORARY TABLE `everlake_preview_guard` (`quest` int unsigned PRIMARY KEY, `title` text NOT NULL, `reward` int unsigned NOT NULL, `eligible` tinyint NOT NULL DEFAULT 0);
UPDATE `everlake_preview_guard` g JOIN `quest_template` q ON q.`ID`=g.`quest` SET g.`eligible`=1 WHERE BINARY q.`LogTitle`=BINARY g.`title` AND q.`RewardSpell`=g.`reward` AND NOT EXISTS (SELECT 1 FROM `quest_reward_display_spell` d WHERE d.`QuestID`=g.`quest`);
-- Preserve every existing quest display set; require captured title and teaching reward
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`QuestID` int unsigned NOT NULL, `Idx` int unsigned NOT NULL, `SpellID` int unsigned NOT NULL, `PlayerConditionID` int unsigned NOT NULL, `Type` int unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`QuestID`, `Idx`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `quest_reward_display_spell` t WHERE t.`QuestID` = s.`QuestID` AND t.`Idx` = s.`Idx`) AND EXISTS (SELECT 1 FROM `everlake_preview_guard` g WHERE g.`quest`=s.`QuestID` AND g.`eligible`=1);
DROP TEMPORARY TABLE `everlake_import_stage`;

DROP TEMPORARY TABLE `everlake_preview_guard`;
SET SESSION autocommit = 1;
